export { useFilterContext } from "./context";
export { FilterInput, FilterRemoveButton } from "./filter-input";
export { FilterOperatorDropdown } from "./filter-operator-dropdown";
export { FilterSubmenuContent } from "./filter-submenu-content";
export { Filters, FiltersContent } from "./filters";
export {
  createOperatorsFromI18n,
  DEFAULT_I18N,
  DEFAULT_OPERATORS,
  getOperatorsForField,
  mergeI18n,
} from "./i18n";
export { FilterValueSelector, SelectOptionsPopover } from "./select-options-popover";
export type {
  CustomRendererProps,
  Filter,
  FilterFieldConfig,
  FilterFieldGroup,
  FilterFieldsConfig,
  FilterGroup,
  FilterI18nConfig,
  FilterIcon,
  FilterOperator,
  FilterOption,
  FilterOptionListRenderProps,
  FilterRadius,
  FilterSize,
  FiltersProps,
  FilterVariant,
} from "./types";
export {
  createFilter,
  createFilterGroup,
  fieldHasOptions,
  filtersContainerVariants,
  flattenFields,
  getFieldsMap,
} from "./utils";

import { createContext, useContext } from "solid-js";

import { DEFAULT_I18N } from "./i18n";
import type { FilterContextValue } from "./types";

const FilterContext = createContext<FilterContextValue>({
  variant: "default",
  size: "default",
  radius: "default",
  i18n: DEFAULT_I18N,
  class: undefined,
  showSearchInput: true,
  trigger: undefined,
  allowMultiple: true,
});

const useFilterContext = () => useContext(FilterContext);

export { FilterContext, useFilterContext };

import { CircleAlert, X } from "lucide-solid";
import type { JSX } from "solid-js";
import { createEffect, createSignal, onCleanup, Show, splitProps } from "solid-js";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/kobalte/ui/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
} from "@/registry/kobalte/ui/input-group";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/kobalte/ui/tooltip";
import { useFilterContext } from "./context";
import type { FilterInputProps, FilterRemoveButtonProps } from "./types";

const IGNORED_VALIDATION_KEYS = [
  "Tab",
  "Escape",
  "Enter",
  "ArrowUp",
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
];

const FilterInput = <T = unknown>(props: FilterInputProps<T>) => {
  const context = useFilterContext();
  const [isValid, setIsValid] = createSignal(true);
  const [validationMessage, setValidationMessage] = createSignal("");
  let inputRef: HTMLInputElement | undefined;

  const [local, others] = splitProps(props, [
    "autofocus",
    "class",
    "field",
    "onBlur",
    "onKeyDown",
    "pattern",
  ]);

  createEffect(() => {
    if (!local.autofocus) return;
    const timer = setTimeout(() => inputRef?.focus(), 300);
    onCleanup(() => clearTimeout(timer));
  });

  // Validation function to check if input matches pattern
  const validateInput = (value: string, pattern?: string): boolean => {
    if (!pattern || !value) return true;
    const regex = new RegExp(pattern);
    return regex.test(value);
  };

  // Get validation message for field type
  const getValidationMessage = (): string => context.i18n.validation.invalid;

  // Handle blur event - validate when user leaves input
  const handleBlur: JSX.EventHandler<HTMLInputElement, FocusEvent> = (event) => {
    const value = event.currentTarget.value;
    const pattern = local.field?.pattern || local.pattern;
    const validation = local.field?.validation;

    // Only validate if there's a value and (pattern or validation function)
    if (value && (pattern || validation)) {
      let valid = true;
      let customMessage = "";

      // If there's a custom validation function, use it
      if (validation) {
        const result = validation(value);
        // Handle both boolean and object return types
        if (typeof result === "boolean") {
          valid = result;
        } else {
          valid = result.valid;
          customMessage = result.message || "";
        }
      } else if (pattern) {
        // Use pattern validation
        valid = validateInput(value, pattern);
      }

      setIsValid(valid);
      setValidationMessage(valid ? "" : customMessage || getValidationMessage());
    } else {
      // Reset validation state for empty values or no validation
      setIsValid(true);
      setValidationMessage("");
    }

    // Call the original onBlur if provided
    local.onBlur?.(event);
  };

  // Handle keydown event - hide validation error when user starts typing
  const handleKeyDown: JSX.EventHandler<HTMLInputElement, KeyboardEvent> = (event) => {
    // Hide validation error when user starts typing (any key except special keys)
    if (!isValid() && !IGNORED_VALIDATION_KEYS.includes(event.key)) {
      setIsValid(true);
      setValidationMessage("");
    }

    // Call the original onKeyDown if provided
    local.onKeyDown?.(event);
  };

  return (
    <InputGroup
      class={cn(
        "w-36",
        // Height follows each style's own control ladder. `default` sets no
        // height on purpose so the style's `.z-input-group` applies (h-8 nova,
        // h-9 maia/luma, h-7 mira, h-10 sera); sm/lg step down/up from it.
        // Base covers nova/lyra/rhea/vega; only deviating styles are listed.
        context.size === "sm" &&
          "h-7! style-maia:h-8! style-luma:h-8! style-mira:h-6! style-sera:h-9!",
        context.size === "lg" &&
          "h-9! style-maia:h-10! style-luma:h-10! style-mira:h-8! style-sera:h-11!",
        // Sera's `.z-input` is `px-0` (underline inputs sit flush); inside a
        // segmented chip that collides with the neighbouring segment, so give
        // the value input the same inline padding sera uses elsewhere.
        "style-sera:px-2.5",
        local.class,
      )}
    >
      <Show when={local.field?.prefix}>
        <InputGroupAddon>
          <InputGroupText>{local.field?.prefix}</InputGroupText>
        </InputGroupAddon>
      </Show>
      <InputGroupInput
        ref={inputRef}
        autofocus={local.autofocus}
        pattern={local.pattern}
        aria-invalid={!isValid()}
        aria-describedby={
          !isValid() && validationMessage() ? `${local.field?.key || "input"}-error` : undefined
        }
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        class={cn(
          context.size === "sm" &&
            "h-7! text-xs style-maia:h-8! style-luma:h-8! style-mira:h-6! style-sera:h-9!",
          context.size === "lg" &&
            "h-9! style-maia:h-10! style-luma:h-10! style-mira:h-8! style-sera:h-11!",
        )}
        {...others}
      />
      <Show when={!isValid() && validationMessage()}>
        <InputGroupAddon align="inline-end">
          <Tooltip>
            <TooltipTrigger as={InputGroupButton} size="icon-xs">
              <CircleAlert class="size-3.5 text-destructive" />
            </TooltipTrigger>
            <TooltipContent>
              <p class="text-sm">{validationMessage()}</p>
            </TooltipContent>
          </Tooltip>
        </InputGroupAddon>
      </Show>

      <Show when={local.field?.suffix}>
        <InputGroupAddon align="inline-end">
          <InputGroupText>{local.field?.suffix}</InputGroupText>
        </InputGroupAddon>
      </Show>
    </InputGroup>
  );
};

const FilterRemoveButton = (props: FilterRemoveButtonProps) => {
  const context = useFilterContext();
  const [local, others] = splitProps(props, ["class", "icon"]);

  return (
    <Button
      variant="outline"
      size={context.size === "sm" ? "icon-sm" : context.size === "lg" ? "icon-lg" : "icon"}
      class={local.class}
      {...others}
    >
      <Show when={local.icon} fallback={<X />}>
        {local.icon}
      </Show>
    </Button>
  );
};

export { FilterInput, FilterRemoveButton };

import { Check } from "lucide-solid";
import { For } from "solid-js";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/kobalte/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/registry/kobalte/ui/dropdown-menu";
import { useFilterContext } from "./context";
import { getOperatorsForField } from "./i18n";
import type { FilterOperatorDropdownProps } from "./types";

const FilterOperatorDropdown = <T = unknown>(props: FilterOperatorDropdownProps<T>) => {
  const context = useFilterContext();
  const operators = () => getOperatorsForField(props.field, props.values, context.i18n);

  // Find the operator label, with fallback to formatted operator name
  const operatorLabel = () =>
    operators().find((operator) => operator.value === props.operator)?.label ||
    context.i18n.helpers.formatOperator(props.operator);

  return (
    <DropdownMenu placement="bottom-start">
      <DropdownMenuTrigger
        as={Button}
        variant="outline"
        size={context.size}
        class="text-muted-foreground hover:text-foreground"
      >
        {operatorLabel()}
      </DropdownMenuTrigger>
      <DropdownMenuContent class="w-fit min-w-fit">
        <For each={operators()}>
          {(operator) => (
            <DropdownMenuItem
              onSelect={() => props.onChange(operator.value)}
              class="flex items-center justify-between data-highlighted:bg-accent data-highlighted:text-accent-foreground"
            >
              <span>{operator.label}</span>
              <Check
                class={cn(
                  "ms-auto text-primary",
                  operator.value === props.operator ? "opacity-100" : "opacity-0",
                )}
              />
            </DropdownMenuItem>
          )}
        </For>
      </DropdownMenuContent>
    </DropdownMenu>
  );
};

export { FilterOperatorDropdown };

import type { Accessor } from "solid-js";
import { createEffect, createSignal, createUniqueId, For, Match, on, Show, Switch } from "solid-js";

import { cn } from "@/lib/utils";
import {
  DropdownMenuCheckboxItem,
  DropdownMenuGroup,
  DropdownMenuSeparator,
} from "@/registry/kobalte/ui/dropdown-menu";
import { Input } from "@/registry/kobalte/ui/input";
import { ScrollArea } from "@/registry/kobalte/ui/scroll-area";
import { DEFAULT_I18N } from "./i18n";
import type { FilterOption, FilterSubmenuContentProps } from "./types";
import { createFieldOptions } from "./use-field-options";
import { renderIcon } from "./utils";

const FilterSubmenuContent = <T = unknown>(props: FilterSubmenuContentProps<T>) => {
  const [searchInput, setSearchInput] = createSignal("");
  const [highlightedIndex, setHighlightedIndex] = createSignal(-1);
  let inputRef: HTMLInputElement | undefined;
  const baseId = createUniqueId();

  const fieldOptions = createFieldOptions<T>(
    () => props.field,
    searchInput,
    () => true,
  );

  createEffect(() => {
    if (!props.isActive) return;
    if (props.field.searchable !== false) {
      inputRef?.focus();
    } else {
      const listbox = document.getElementById(`${baseId}-listbox`);
      listbox?.focus();
    }
  });

  createEffect(() => {
    if (highlightedIndex() >= 0 && props.isActive) {
      const element = document.getElementById(`${baseId}-item-${highlightedIndex()}`);
      element?.scrollIntoView({ block: "nearest" });
    }
  });

  const filteredOptions = (): FilterOption<T>[] => {
    // Async fields: keep selected values first (resolved from cache so they
    // stay labelled), then the loader's already-query-filtered results.
    if (fieldOptions.isAsync()) {
      const selected = new Set(props.currentValues);
      return [
        ...fieldOptions.resolveSelected(props.currentValues),
        ...fieldOptions.options().filter((option) => !selected.has(option.value)),
      ];
    }
    return (
      props.field.options?.filter((option) => {
        const isSelected = props.currentValues.includes(option.value);
        if (isSelected) return true;
        if (!searchInput()) return true;
        return option.label.toLowerCase().includes(searchInput().toLowerCase());
      }) ?? []
    );
  };

  const renderOptionRow = (option: FilterOption<T>, index: Accessor<number>) => {
    const isSelected = () => props.currentValues.includes(option.value);
    const isHighlighted = () => highlightedIndex() === index();

    return (
      <DropdownMenuCheckboxItem
        id={`${baseId}-item-${index()}`}
        role="option"
        aria-selected={isHighlighted()}
        data-highlighted={isHighlighted() || undefined}
        onMouseEnter={() => setHighlightedIndex(index())}
        checked={isSelected()}
        closeOnSelect={!props.isMultiSelect}
        class={cn(
          "data-highlighted:bg-accent data-highlighted:text-accent-foreground",
          option.class,
        )}
        onChange={() => props.onToggle(option.value as T, isSelected())}
      >
        {renderIcon(option.icon)}
        <span class="truncate">{option.label}</span>
      </DropdownMenuCheckboxItem>
    );
  };

  const renderOptionItem = (option: FilterOption<T>, index: number) =>
    renderOptionRow(option, () => index);

  // One deterministic rule instead of upstream's reset-then-rehighlight pair
  // (see the same note in filters.tsx): the first row is highlighted whenever
  // this submenu is active and something matches.
  createEffect(
    on([searchInput, () => props.isActive, filteredOptions], ([, isActive, options]) => {
      setHighlightedIndex(isActive && options.length > 0 ? 0 : -1);
    }),
  );

  const selectHighlighted = () => {
    const option = filteredOptions()[highlightedIndex()];
    if (!option) return;
    props.onToggle(option.value as T, props.currentValues.includes(option.value));
    if (!props.isMultiSelect) {
      props.onBack?.();
    }
  };

  const handleListKeyDown = (event: KeyboardEvent) => {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      if (filteredOptions().length > 0) {
        setHighlightedIndex((previous) =>
          previous < filteredOptions().length - 1 ? previous + 1 : 0,
        );
      }
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      if (filteredOptions().length > 0) {
        setHighlightedIndex((previous) =>
          previous > 0 ? previous - 1 : filteredOptions().length - 1,
        );
      }
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      props.onBack?.();
    } else if (event.key === "Enter" && highlightedIndex() >= 0) {
      event.preventDefault();
      selectHighlighted();
    } else if (event.key === "Escape") {
      event.preventDefault();
      props.onClose?.();
    }
    event.stopPropagation();
  };

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: pointer hover mirrors the upstream submenu activation, keyboard is handled by the listbox below
    <div class="flex flex-col" onMouseEnter={() => props.onActive?.()}>
      <Show when={props.field.searchable !== false}>
        <Input
          ref={inputRef}
          role="combobox"
          aria-autocomplete="list"
          aria-expanded={true}
          aria-haspopup="listbox"
          aria-controls={`${baseId}-listbox`}
          aria-activedescendant={
            highlightedIndex() >= 0 ? `${baseId}-item-${highlightedIndex()}` : undefined
          }
          placeholder={props.i18n.placeholders.searchField(props.field.label || "")}
          class={cn(
            "h-8 rounded-none border-0 bg-transparent! px-2 text-sm shadow-none",
            "focus-visible:border-border focus-visible:ring-0 focus-visible:ring-offset-0",
            props.isActive && "placeholder:text-foreground",
          )}
          value={searchInput()}
          onBlur={() => {
            if (props.isActive) inputRef?.focus();
          }}
          onInput={(event) => setSearchInput(event.currentTarget.value)}
          onFocus={() => props.onActive?.()}
          onMouseEnter={(event) => {
            props.onActive?.();
            event.stopPropagation();
          }}
          onClick={(event) => event.stopPropagation()}
          onKeyDown={handleListKeyDown}
        />
        <DropdownMenuSeparator />
      </Show>
      <div class="relative flex max-h-full">
        <div
          class="flex max-h-[min(var(--kb-popper-content-available-height),24rem)] w-full scroll-pt-2 scroll-pb-2 flex-col overscroll-contain outline-hidden"
          role="listbox"
          id={`${baseId}-listbox`}
          tabindex={props.field.searchable === false ? 0 : -1}
          onKeyDown={(event) => {
            if (props.field.searchable === false) {
              handleListKeyDown(event);
            }
          }}
        >
          <Switch>
            <Match when={fieldOptions.loading() && filteredOptions().length === 0}>
              <div class="py-2 text-center text-muted-foreground text-sm">
                {props.i18n.loadingOptions ?? DEFAULT_I18N.loadingOptions}
              </div>
            </Match>
            <Match when={fieldOptions.error()}>
              <div class="py-2 text-center text-muted-foreground text-sm">
                {props.i18n.errorLoadingOptions ?? DEFAULT_I18N.errorLoadingOptions}
              </div>
            </Match>
            <Match when={filteredOptions().length === 0}>
              <div class="py-2 text-center text-muted-foreground text-sm">
                {props.i18n.noResultsFound}
              </div>
            </Match>
            <Match when={props.field.renderOptionList}>
              {(renderOptionList) =>
                // Getters keep this `Match` from re-running (and re-creating the
                // consumer's list component) on every keystroke / highlight move.
                renderOptionList()({
                  get options() {
                    return filteredOptions();
                  },
                  get highlightedIndex() {
                    return highlightedIndex();
                  },
                  renderOption: renderOptionItem,
                })
              }
            </Match>
            <Match when={true}>
              <ScrollArea class="size-full min-h-0 **:data-[slot=scroll-area-scrollbar]:m-0 [&_[data-slot=scroll-area-viewport]]:h-full [&_[data-slot=scroll-area-viewport]]:overscroll-contain">
                <DropdownMenuGroup>
                  <For each={filteredOptions()}>
                    {(option, index) => renderOptionRow(option, index)}
                  </For>
                </DropdownMenuGroup>
              </ScrollArea>
            </Match>
          </Switch>
        </div>
      </div>
    </div>
  );
};

export { FilterSubmenuContent };

import { Plus } from "lucide-solid";
import type { ValidComponent } from "solid-js";
import {
  createEffect,
  createMemo,
  createSignal,
  createUniqueId,
  For,
  mergeProps,
  on,
  onCleanup,
  Show,
} from "solid-js";

import { cn } from "@/lib/utils";
import { Button } from "@/registry/kobalte/ui/button";
import { ButtonGroup, ButtonGroupText } from "@/registry/kobalte/ui/button-group";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/registry/kobalte/ui/dropdown-menu";
import { Input } from "@/registry/kobalte/ui/input";
import { Kbd } from "@/registry/kobalte/ui/kbd";
import { ScrollArea } from "@/registry/kobalte/ui/scroll-area";
import { FilterContext, useFilterContext } from "./context";
import { FilterRemoveButton } from "./filter-input";
import { FilterOperatorDropdown } from "./filter-operator-dropdown";
import { FilterSubmenuContent } from "./filter-submenu-content";
import { mergeI18n } from "./i18n";
import { FilterValueSelector } from "./select-options-popover";
import type {
  Filter,
  FilterContextValue,
  FilterFieldConfig,
  FilterRadius,
  FilterSize,
  FiltersContentProps,
  FiltersProps,
  FilterVariant,
} from "./types";
import {
  createFilter,
  fieldHasOptions,
  filtersContainerVariants,
  flattenFields,
  getFieldsMap,
  renderIcon,
} from "./utils";

// Sera is an underline style: its group text and input group carry only a
// bottom border. Normalise the boxed segments (the operator, value and remove
// buttons) to the same treatment so the whole chip reads as one underlined
// group instead of mixing boxes and rules.
const FILTER_CHIP_CLASS =
  "style-sera:*:rounded-none style-sera:*:border-transparent style-sera:*:border-b-input";

const hasSubMenu = <T,>(field: FilterFieldConfig<T>): boolean =>
  (field.type === "select" || field.type === "multiselect") && fieldHasOptions(field);

const FiltersContent = <T = unknown>(props: FiltersContentProps<T>) => {
  const context = useFilterContext();
  const fieldsMap = createMemo(() => getFieldsMap(props.fields));
  // `<For>` diffs by reference and every update replaces the filter object, so
  // iterating the filters directly would tear down and rebuild a chip on each
  // keystroke (losing input focus and any custom control's internal state).
  // Iterate the stable string ids instead — the React `key={filter.id}` this
  // was ported from behaves the same way.
  const filterIds = createMemo(() => props.filters.map((filter) => filter.id));

  const updateFilter = (filterId: string, updates: Partial<Filter<T>>) => {
    props.onChange(
      props.filters.map((filter) => {
        if (filter.id === filterId) {
          const updatedFilter = { ...filter, ...updates };
          if (updates.operator === "empty" || updates.operator === "not_empty") {
            updatedFilter.values = [] as T[];
          }
          return updatedFilter;
        }
        return filter;
      }),
    );
  };

  const removeFilter = (filterId: string) => {
    props.onChange(props.filters.filter((filter) => filter.id !== filterId));
  };

  return (
    <div
      class={cn(
        filtersContainerVariants({ variant: context.variant, size: context.size }),
        context.class,
      )}
    >
      <For each={filterIds()}>
        {(filterId) => {
          const filter = () => props.filters.find((entry) => entry.id === filterId);

          return (
            <Show when={filter()}>
              {(currentFilter) => (
                <Show when={fieldsMap()[currentFilter().field]}>
                  {(field) => (
                    <ButtonGroup class={FILTER_CHIP_CLASS}>
                      <ButtonGroupText>
                        {renderIcon(field().icon)}
                        {field().label}
                      </ButtonGroupText>

                      <FilterOperatorDropdown<T>
                        field={field()}
                        operator={currentFilter().operator}
                        values={currentFilter().values}
                        onChange={(operator) => updateFilter(filterId, { operator })}
                      />

                      <FilterValueSelector<T>
                        field={field()}
                        values={currentFilter().values}
                        onChange={(values) => updateFilter(filterId, { values })}
                        operator={currentFilter().operator}
                        autofocus={false}
                      />

                      <FilterRemoveButton onClick={() => removeFilter(filterId)} />
                    </ButtonGroup>
                  )}
                </Show>
              )}
            </Show>
          );
        }}
      </For>
    </div>
  );
};

const Filters = <T = unknown>(rawProps: FiltersProps<T>) => {
  const props = mergeProps(
    {
      variant: "default" as FilterVariant,
      size: "default" as FilterSize,
      radius: "default" as FilterRadius,
      showSearchInput: true,
      allowMultiple: true,
      enableShortcut: false,
      shortcutKey: "f",
      shortcutLabel: "F",
    },
    rawProps,
  );

  // See `FiltersContent`: iterate stable ids so a chip survives its filter
  // object being replaced by an update.
  const filterIds = createMemo(() => props.filters.map((filter) => filter.id));
  const [addFilterOpen, setAddFilterOpen] = createSignal(false);
  const [menuSearchInput, setMenuSearchInput] = createSignal("");
  const [activeMenu, setActiveMenu] = createSignal<string>("root");
  const [openSubMenu, setOpenSubMenu] = createSignal<string | null>(null);
  const [highlightedIndex, setHighlightedIndex] = createSignal(-1);
  const [lastAddedFilterId, setLastAddedFilterId] = createSignal<string | null>(null);
  // Track which filter instance is being built in the current Add Filter menu
  // session. Maps fieldKey -> unique filterId created during this open session.
  const [sessionFilterIds, setSessionFilterIds] = createSignal<Record<string, string>>({});
  let rootInputRef: HTMLInputElement | undefined;
  const rootId = createUniqueId();

  createEffect(() => {
    if (!props.enableShortcut) return;
    const shortcutKey = props.shortcutKey;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key.toLowerCase() === shortcutKey.toLowerCase() &&
        !addFilterOpen() &&
        !(
          document.activeElement instanceof HTMLInputElement ||
          document.activeElement instanceof HTMLTextAreaElement
        )
      ) {
        event.preventDefault();
        setAddFilterOpen(true);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    onCleanup(() => window.removeEventListener("keydown", handleKeyDown));
  });

  createEffect(() => {
    if (addFilterOpen() && activeMenu() === "root") {
      rootInputRef?.focus();
    }
  });

  // The menu popup mounts after this component's effects have flushed, so the
  // effect above cannot focus the freshly created input. Claim focus from the
  // ref on the next tick, which lands after Kobalte's open auto-focus.
  const focusRootInput = (element: HTMLInputElement) => {
    rootInputRef = element;
    setTimeout(() => {
      if (activeMenu() === "root") element.focus();
    }, 0);
  };

  createEffect(() => {
    if (highlightedIndex() >= 0 && addFilterOpen()) {
      const element = document.getElementById(`${rootId}-item-${highlightedIndex()}`);
      element?.scrollIntoView({ block: "nearest" });
    }
  });

  createEffect(() => {
    if (!addFilterOpen()) {
      setOpenSubMenu(null);
    }
  });

  createEffect(() => {
    if (!lastAddedFilterId()) return;
    const timer = setTimeout(() => setLastAddedFilterId(null), 1000);
    onCleanup(() => clearTimeout(timer));
  });

  const mergedI18n = createMemo(() => mergeI18n(props.i18n));

  const fieldsMap = createMemo(() => getFieldsMap(props.fields));

  const updateFilter = (filterId: string, updates: Partial<Filter<T>>) => {
    props.onChange(
      props.filters.map((filter) => {
        if (filter.id === filterId) {
          const updatedFilter = { ...filter, ...updates };
          if (updates.operator === "empty" || updates.operator === "not_empty") {
            updatedFilter.values = [] as T[];
          }
          return updatedFilter;
        }
        return filter;
      }),
    );
  };

  const removeFilter = (filterId: string) => {
    props.onChange(props.filters.filter((filter) => filter.id !== filterId));
  };

  const addFilter = (fieldKey: string) => {
    const field = fieldsMap()[fieldKey];
    if (field?.key) {
      const defaultOperator =
        field.defaultOperator || (field.type === "multiselect" ? "is_any_of" : "is");
      const defaultValues: unknown[] = field.type === "text" ? [""] : [];
      const newFilter = createFilter<T>(fieldKey, defaultOperator, defaultValues as T[]);
      setLastAddedFilterId(newFilter.id);
      props.onChange([...props.filters, newFilter]);
      setAddFilterOpen(false);
      setMenuSearchInput("");
    }
  };

  const selectableFields = createMemo(() => {
    const flatFields = flattenFields(props.fields);
    return flatFields.filter((field) => {
      if (!field.key || field.type === "separator") return false;
      if (props.allowMultiple) return true;
      return !props.filters.some((filter) => filter.field === field.key);
    });
  });

  const filteredFields = createMemo(() =>
    selectableFields().filter(
      (field) =>
        !menuSearchInput() || field.label?.toLowerCase().includes(menuSearchInput().toLowerCase()),
    ),
  );

  // Upstream splits this across two effects — one resetting to -1 whenever the
  // query changes, one re-highlighting the first row when the match count
  // changes. In Solid both would land in the same flush and race, so keep a
  // single deterministic rule: the first match is highlighted, or nothing when
  // the menu is closed or nothing matches.
  createEffect(
    on([menuSearchInput, addFilterOpen, filteredFields], ([, isOpen, fields]) => {
      setHighlightedIndex(isOpen && fields.length > 0 ? 0 : -1);
    }),
  );

  const toggleSubMenu = (fieldKey: string) => {
    if (openSubMenu() === fieldKey) {
      setOpenSubMenu(null);
      setActiveMenu("root");
    } else {
      setOpenSubMenu(fieldKey);
      setActiveMenu(fieldKey);
    }
  };

  const contextValue: FilterContextValue = {
    get variant() {
      return props.variant;
    },
    get size() {
      return props.size;
    },
    get radius() {
      return props.radius;
    },
    get i18n() {
      return mergedI18n();
    },
    get class() {
      return props.class;
    },
    get showSearchInput() {
      return props.showSearchInput;
    },
    get trigger() {
      return props.trigger;
    },
    get allowMultiple() {
      return props.allowMultiple;
    },
  };

  return (
    <FilterContext.Provider value={contextValue}>
      <div
        class={cn(
          filtersContainerVariants({ variant: props.variant, size: props.size }),
          props.class,
        )}
      >
        <Show when={selectableFields().length > 0}>
          <DropdownMenu
            placement="bottom-start"
            open={addFilterOpen()}
            onOpenChange={(open) => {
              setAddFilterOpen(open);
              if (!open) {
                setMenuSearchInput("");
                setSessionFilterIds({});
              } else {
                setActiveMenu("root");
              }
            }}
          >
            <Show
              when={props.trigger}
              fallback={
                <DropdownMenuTrigger as={Button} variant="outline">
                  <Plus />
                  {mergedI18n().addFilter}
                </DropdownMenuTrigger>
              }
            >
              {/* Solid has no `cloneElement`: the consumer supplies a component
                  and Kobalte's polymorphic `as` forwards the trigger props to it. */}
              {(trigger) => (
                <DropdownMenuTrigger as={trigger() as ValidComponent} class={undefined} />
              )}
            </Show>
            <DropdownMenuContent class={cn("w-[220px]", props.menuPopupClassName)}>
              <Show when={props.showSearchInput}>
                <div class="relative">
                  <Input
                    ref={focusRootInput}
                    role="combobox"
                    aria-controls={`${rootId}-listbox`}
                    aria-activedescendant={
                      highlightedIndex() >= 0 ? `${rootId}-item-${highlightedIndex()}` : undefined
                    }
                    placeholder={mergedI18n().searchFields}
                    class={cn(
                      "h-8 rounded-none border-0 bg-transparent! px-2 text-sm shadow-none",
                      "focus-visible:border-border focus-visible:ring-0 focus-visible:ring-offset-0",
                      activeMenu() === "root" && "placeholder:text-foreground",
                    )}
                    value={menuSearchInput()}
                    onFocus={() => setActiveMenu("root")}
                    onMouseEnter={() => setActiveMenu("root")}
                    onBlur={() => {
                      if (activeMenu() === "root") rootInputRef?.focus();
                    }}
                    onInput={(event) => setMenuSearchInput(event.currentTarget.value)}
                    onClick={(event) => event.stopPropagation()}
                    onKeyDown={(event) => {
                      if (event.key === "ArrowDown") {
                        event.preventDefault();
                        if (filteredFields().length > 0) {
                          setHighlightedIndex((previous) =>
                            previous < filteredFields().length - 1 ? previous + 1 : 0,
                          );
                        }
                      } else if (event.key === "ArrowUp") {
                        event.preventDefault();
                        if (filteredFields().length > 0) {
                          setHighlightedIndex((previous) =>
                            previous > 0 ? previous - 1 : filteredFields().length - 1,
                          );
                        }
                      } else if (
                        (event.key === "ArrowRight" || event.key === "ArrowLeft") &&
                        highlightedIndex() >= 0
                      ) {
                        const field = filteredFields()[highlightedIndex()];

                        if (event.key === "ArrowRight" && field && hasSubMenu(field)) {
                          event.preventDefault();
                          setOpenSubMenu(field.key || null);
                          setActiveMenu(field.key || "root");
                        } else if (event.key === "ArrowLeft") {
                          event.preventDefault();
                          if (openSubMenu()) {
                            setOpenSubMenu(null);
                            setActiveMenu("root");
                          }
                        }
                      } else if (event.key === "Enter" && highlightedIndex() >= 0) {
                        event.preventDefault();
                        const field = filteredFields()[highlightedIndex()];
                        if (field?.key) {
                          if (hasSubMenu(field)) {
                            toggleSubMenu(field.key);
                          } else {
                            addFilter(field.key);
                          }
                        }
                      } else if (event.key === "Escape") {
                        setAddFilterOpen(false);
                      }
                      event.stopPropagation();
                    }}
                  />
                  <Show when={props.enableShortcut && props.shortcutLabel}>
                    <Kbd class="-translate-y-1/2 absolute top-1/2 right-2 border bg-background">
                      {props.shortcutLabel}
                    </Kbd>
                  </Show>
                </div>
                <DropdownMenuSeparator />
              </Show>

              <div class="relative flex max-h-full">
                <div
                  class="flex max-h-[min(var(--kb-popper-content-available-height),24rem)] w-full scroll-pt-2 scroll-pb-2 flex-col overscroll-contain"
                  role="listbox"
                  id={`${rootId}-listbox`}
                  onMouseEnter={() => setActiveMenu("root")}
                >
                  <ScrollArea class="**:data-[slot=scroll-area-scrollbar]:m-0">
                    <Show
                      when={filteredFields().length > 0}
                      fallback={
                        <div class="py-2 text-center text-muted-foreground text-sm">
                          {mergedI18n().noFieldsFound}
                        </div>
                      }
                    >
                      <For each={filteredFields()}>
                        {(field, index) => {
                          const isHighlighted = () => highlightedIndex() === index();
                          const itemId = () => `${rootId}-item-${index()}`;
                          const fieldKey = field.key as string;
                          const isMultiSelect = field.type === "multiselect";
                          const sessionFilter = () => {
                            const sessionFilterId = sessionFilterIds()[fieldKey];
                            return sessionFilterId
                              ? props.filters.find((filter) => filter.id === sessionFilterId)
                              : undefined;
                          };
                          const currentValues = () => sessionFilter()?.values ?? [];

                          return (
                            <Show
                              when={hasSubMenu(field)}
                              fallback={
                                <DropdownMenuItem
                                  id={itemId()}
                                  role="option"
                                  aria-selected={isHighlighted()}
                                  data-highlighted={isHighlighted() || undefined}
                                  onMouseEnter={() => setHighlightedIndex(index())}
                                  onSelect={() => field.key && addFilter(field.key)}
                                  class="data-highlighted:bg-accent data-highlighted:text-accent-foreground"
                                >
                                  {renderIcon(field.icon)}
                                  <span>{field.label}</span>
                                </DropdownMenuItem>
                              }
                            >
                              <DropdownMenuSub
                                open={openSubMenu() === fieldKey}
                                onOpenChange={(open) => {
                                  if (open) {
                                    setOpenSubMenu(fieldKey);
                                  } else if (openSubMenu() === fieldKey) {
                                    setOpenSubMenu(null);
                                    setActiveMenu("root");
                                  }
                                }}
                              >
                                <DropdownMenuSubTrigger
                                  id={itemId()}
                                  role="option"
                                  aria-selected={isHighlighted()}
                                  data-highlighted={isHighlighted() || undefined}
                                  onMouseEnter={() => {
                                    setHighlightedIndex(index());
                                    setActiveMenu("root");
                                  }}
                                  class="data-expanded:bg-accent data-expanded:text-accent-foreground data-highlighted:bg-accent data-highlighted:text-accent-foreground"
                                >
                                  {renderIcon(field.icon)}
                                  <span>{field.label}</span>
                                </DropdownMenuSubTrigger>
                                <DropdownMenuSubContent class="w-[200px]">
                                  <FilterSubmenuContent<T>
                                    field={field}
                                    currentValues={currentValues()}
                                    isMultiSelect={isMultiSelect}
                                    i18n={mergedI18n()}
                                    isActive={activeMenu() === fieldKey}
                                    onActive={() => {
                                      if (field.searchable !== false) {
                                        setActiveMenu(fieldKey);
                                      }
                                    }}
                                    onBack={() => {
                                      setOpenSubMenu(null);
                                      setActiveMenu("root");
                                    }}
                                    onClose={() => setAddFilterOpen(false)}
                                    onToggle={(value, isSelected) => {
                                      if (isMultiSelect) {
                                        const nextValues = isSelected
                                          ? (currentValues().filter(
                                              (current) => current !== value,
                                            ) as T[])
                                          : ([...currentValues(), value] as T[]);
                                        const filter = sessionFilter();

                                        if (filter) {
                                          if (nextValues.length === 0) {
                                            props.onChange(
                                              props.filters.filter(
                                                (current) => current.id !== filter.id,
                                              ),
                                            );
                                            setSessionFilterIds((previous) => ({
                                              ...previous,
                                              [fieldKey]: "",
                                            }));
                                          } else {
                                            props.onChange(
                                              props.filters.map((current) =>
                                                current.id === filter.id
                                                  ? { ...current, values: nextValues }
                                                  : current,
                                              ),
                                            );
                                          }
                                        } else {
                                          const newFilter = createFilter<T>(
                                            fieldKey,
                                            field.defaultOperator || "is_any_of",
                                            nextValues,
                                          );
                                          props.onChange([...props.filters, newFilter]);
                                          setSessionFilterIds((previous) => ({
                                            ...previous,
                                            [fieldKey]: newFilter.id,
                                          }));
                                        }
                                      } else {
                                        const newFilter = createFilter<T>(
                                          fieldKey,
                                          field.defaultOperator || "is",
                                          [value] as T[],
                                        );
                                        setLastAddedFilterId(newFilter.id);
                                        props.onChange([...props.filters, newFilter]);
                                        setAddFilterOpen(false);
                                      }
                                    }}
                                  />
                                </DropdownMenuSubContent>
                              </DropdownMenuSub>
                            </Show>
                          );
                        }}
                      </For>
                    </Show>
                  </ScrollArea>
                </div>
              </div>
            </DropdownMenuContent>
          </DropdownMenu>
        </Show>

        <For each={filterIds()}>
          {(filterId) => {
            const filter = () => props.filters.find((entry) => entry.id === filterId);
            // Read once at creation: the chip is mounted the moment its filter
            // is added, so this mirrors React's mount-time `autoFocus`.
            const autofocus = filterId === lastAddedFilterId();

            return (
              <Show when={filter()}>
                {(currentFilter) => (
                  <Show when={fieldsMap()[currentFilter().field]}>
                    {(field) => (
                      <ButtonGroup class={FILTER_CHIP_CLASS}>
                        <ButtonGroupText class="bg-background dark:bg-input/30">
                          {renderIcon(field().icon)}
                          {field().label}
                        </ButtonGroupText>
                        <FilterOperatorDropdown<T>
                          field={field()}
                          operator={currentFilter().operator}
                          values={currentFilter().values}
                          onChange={(operator) => updateFilter(filterId, { operator })}
                        />
                        <FilterValueSelector<T>
                          field={field()}
                          values={currentFilter().values}
                          operator={currentFilter().operator}
                          onChange={(values) => updateFilter(filterId, { values })}
                          autofocus={autofocus}
                        />
                        <FilterRemoveButton onClick={() => removeFilter(filterId)} />
                      </ButtonGroup>
                    )}
                  </Show>
                )}
              </Show>
            );
          }}
        </For>
      </div>
    </FilterContext.Provider>
  );
};

export { Filters, FiltersContent };

