import type { Accessor } from "solid-js";
import { createEffect, createSignal, on, onCleanup, untrack } from "solid-js";

import type { FilterFieldConfig, FilterOption, ResolvedFieldOptions } from "./types";

// Value->option cache shared across every component instance rendering the
// SAME field object (the Add Filter submenu and the active-filter chip both
// receive the same config reference from the fields map). Keyed by the field
// object so it is shared when fields are memoized and garbage-collected
// otherwise. This keeps a value selected in the submenu labelled in the chip.
const fieldOptionCaches = new WeakMap<object, Map<unknown, FilterOption>>();

const getFieldOptionCache = <T = unknown>(field: FilterFieldConfig<T>): Map<T, FilterOption<T>> => {
  let cache = fieldOptionCaches.get(field as object);
  if (!cache) {
    cache = new Map();
    fieldOptionCaches.set(field as object, cache);
  }
  return cache as unknown as Map<T, FilterOption<T>>;
};

/**
 * Resolves a field's options for a popover/submenu. Static fields return their
 * list verbatim (unchanged legacy behavior). Async fields (`loadOptions`)
 * debounce the query, guard against out-of-order responses, and expose
 * loading/error state plus a value->label cache.
 */
const createFieldOptions = <T = unknown>(
  field: Accessor<FilterFieldConfig<T>>,
  searchInput: Accessor<string>,
  enabled: Accessor<boolean>,
): ResolvedFieldOptions<T> => {
  const isAsync = () => typeof field().loadOptions === "function";

  // Seed the shared cache from any static options an async field also provides
  // (static fields never read this cache, so skip the work for them). This runs
  // synchronously, like upstream's render-time seeding: deferring it to an
  // effect would let the first paint fall back to `String(value)` for a
  // pre-selected chip.
  const seedCache = () => {
    const current = untrack(field);
    if (typeof current.loadOptions !== "function" || !current.options) return;
    const cache = getFieldOptionCache(current);
    for (const option of current.options) {
      cache.set(option.value, option);
    }
  };

  seedCache();

  const [asyncOptions, setAsyncOptions] = createSignal<FilterOption<T>[]>(
    untrack(field).options ?? [],
  );
  const [loading, setLoading] = createSignal(false);
  const [error, setError] = createSignal(false);

  // Debounce the query for async fields to avoid a request per keystroke.
  const [debouncedQuery, setDebouncedQuery] = createSignal(untrack(searchInput));
  createEffect(() => {
    const query = searchInput();
    if (!isAsync()) return;
    const timer = setTimeout(() => setDebouncedQuery(query), 250);
    onCleanup(() => clearTimeout(timer));
  });

  let requestId = 0;
  // Only the debounced query and the enabled flag retrigger a load. The field
  // itself is read untracked so an inline (unmemoized) config object does not
  // cancel and refire the in-flight request on every parent update.
  createEffect(
    on([debouncedQuery, enabled], ([query, isEnabled]) => {
      const current = untrack(field);
      const loader = current.loadOptions;
      if (!loader || !isEnabled) return;

      const currentRequestId = ++requestId;
      let cancelled = false;
      setLoading(true);
      setError(false);

      Promise.resolve()
        .then(() => loader(query))
        .then((result) => {
          // Ignore stale responses (out-of-order guard).
          if (cancelled || currentRequestId !== requestId) return;
          const cache = getFieldOptionCache(current);
          for (const option of result) cache.set(option.value, option);
          setAsyncOptions(result);
          setLoading(false);
          setError(false);
        })
        .catch(() => {
          if (cancelled || currentRequestId !== requestId) return;
          setLoading(false);
          setError(true);
        });

      onCleanup(() => {
        cancelled = true;
      });
    }),
  );

  const resolveSelected = (values: T[]): FilterOption<T>[] => {
    seedCache();
    const cache = getFieldOptionCache(untrack(field));
    return values.map((value) => cache.get(value) ?? { value, label: String(value) });
  };

  return {
    isAsync,
    options: () => (isAsync() ? asyncOptions() : (field().options ?? [])),
    loading: () => isAsync() && loading(),
    error: () => isAsync() && error(),
    resolveSelected,
  };
};

export { createFieldOptions, getFieldOptionCache };

import { cva } from "class-variance-authority";

import type { JSX } from "solid-js";

import type {
  Filter,
  FilterFieldConfig,
  FilterFieldGroup,
  FilterFieldsConfig,
  FilterGroup,
  FilterIcon,
} from "./types";

// Container variant for filters wrapper
const filtersContainerVariants = cva("flex flex-wrap items-center", {
  variants: {
    variant: {
      solid: "gap-2",
      default: "",
    },
    size: {
      sm: "gap-1.5",
      default: "gap-2.5",
      lg: "gap-3.5",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

// Icons may be given as JSX or as a thunk. Solid resolves function children on
// insert, but `JSX.Element` does not include functions in its type, so unwrap
// at the render site. Called from a JSX expression, the thunk still runs inside
// the insert effect, which is what keeps it lazy (and hydration-safe).
const renderIcon = (icon?: FilterIcon): JSX.Element =>
  typeof icon === "function" ? (icon() as JSX.Element) : (icon as JSX.Element);

// Helper functions to handle both flat and grouped field configurations
const isFieldGroup = <T = unknown>(
  item: FilterFieldConfig<T> | FilterFieldGroup<T>,
): item is FilterFieldGroup<T> => {
  return "fields" in item && Array.isArray(item.fields);
};

// Helper function to check if a FilterFieldConfig is a group-level configuration
const isGroupLevelField = <T = unknown>(field: FilterFieldConfig<T>): boolean => {
  return Boolean(field.group && field.fields);
};

const flattenFields = <T = unknown>(fields: FilterFieldsConfig<T>): FilterFieldConfig<T>[] => {
  const flat: FilterFieldConfig<T>[] = [];
  for (const item of fields) {
    if (isFieldGroup(item)) {
      flat.push(...item.fields);
      continue;
    }
    // Handle group-level fields (new structure)
    if (isGroupLevelField(item)) {
      flat.push(...(item.fields as FilterFieldConfig<T>[]));
      continue;
    }
    flat.push(item);
  }
  return flat;
};

const getFieldsMap = <T = unknown>(
  fields: FilterFieldsConfig<T>,
): Record<string, FilterFieldConfig<T>> => {
  const flatFields = flattenFields(fields);
  return flatFields.reduce(
    (acc, field) => {
      // Only add fields that have a key (skip group-level configurations)
      if (field.key) {
        acc[field.key] = field;
      }
      return acc;
    },
    {} as Record<string, FilterFieldConfig<T>>,
  );
};

// Whether a field exposes any option source (a static list or an async loader).
// IMPORTANT: never gate on `field.options?.length` once `loadOptions` exists —
// a function's `.length` is its arity, not an option count, which silently
// breaks the submenu gate for async fields.
const fieldHasOptions = <T = unknown>(field: FilterFieldConfig<T>): boolean =>
  (field.options?.length ?? 0) > 0 || typeof field.loadOptions === "function";

const createFilter = <T = unknown>(
  field: string,
  operator?: string,
  values: T[] = [],
): Filter<T> => ({
  id: `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
  field,
  operator: operator || "is",
  values,
});

const createFilterGroup = <T = unknown>(
  id: string,
  label: string,
  fields: FilterFieldConfig<T>[],
  initialFilters: Filter<T>[] = [],
): FilterGroup<T> => ({
  id,
  label,
  filters: initialFilters,
  fields,
});

export {
  createFilter,
  createFilterGroup,
  fieldHasOptions,
  filtersContainerVariants,
  flattenFields,
  getFieldsMap,
  isFieldGroup,
  isGroupLevelField,
  renderIcon,
};
